INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('820541c3-27fc-469b-bf35-581430064da1', 'life_insurance', NULL, 'What is the human life value approach?', '¿Qué es el enfoque de valor de vida humana?', '["Calculating insurance needs based on the present value of future earnings", "Based on debts only", "Arbitrary amounts", "Based on age only"]', '["Calcular necesidades de seguro basándose en el valor presente de ingresos futuros", "Basado solo en deudas", "Montos arbitrarios", "Basado solo en edad"]', 0, 'The human life value approach determines insurance needs by calculating the present value of expected future income.', 'El enfoque de valor de vida humana determina las necesidades de seguro calculando el valor presente del ingreso futuro esperado.', true, '2026-01-14 23:01:15.722356', '2026-01-14 23:01:15.722356') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('82648de4-2c37-4472-9f7d-5fb01a049a9c', 'life_insurance', NULL, 'Is cash value growth in a life insurance policy taxable?', '¿Es gravable el crecimiento del valor en efectivo en una póliza de seguro de vida?', '["No, cash value grows tax-deferred", "Yes, taxed annually", "Taxed monthly", "Taxed at withdrawal only"]', '["No, el valor en efectivo crece con impuestos diferidos", "Sí, gravado anualmente", "Gravado mensualmente", "Gravado solo al retiro"]', 0, 'Cash value in a life insurance policy grows on a tax-deferred basis until withdrawn.', 'El valor en efectivo en una póliza de seguro de vida crece con impuestos diferidos hasta que se retira.', true, '2026-01-14 22:54:57.474237', '2026-01-14 22:54:57.474237') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('82e59fc0-39e9-4ec4-810c-7aea11b57a8c', 'life_insurance', NULL, 'What are non-forfeiture options?', '¿Qué son las opciones de no confiscación?', '["Options that allow policyholders to receive value from a policy if it lapses", "Types of riders", "Coverage limits", "Premium payment options"]', '["Opciones que permiten a los asegurados recibir valor de una póliza si caduca", "Tipos de anexos", "Límites de cobertura", "Opciones de pago de prima"]', 0, 'Non-forfeiture options allow policyholders to receive some value from their permanent life insurance policy if they stop paying premiums.', 'Las opciones de no confiscación permiten a los asegurados recibir algún valor de su póliza de seguro de vida permanente si dejan de pagar primas.', true, '2026-01-14 18:28:35.650562', '2026-01-14 18:28:35.650562') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('83233cfc-0f08-41dc-b191-87fa2f997a1d', 'life_insurance', NULL, 'What is the purpose of life insurance?', '¿Cuál es el propósito del seguro de vida?', '["To provide financial protection for beneficiaries upon death of the insured", "To pay for medical expenses", "To insure property", "To provide retirement income"]', '["Proporcionar protección financiera para beneficiarios tras la muerte del asegurado", "Pagar gastos médicos", "Asegurar propiedad", "Proporcionar ingresos de jubilación"]', 0, 'Life insurance provides a death benefit to named beneficiaries to replace income and cover expenses after the insured''s death.', 'El seguro de vida proporciona un beneficio por muerte a beneficiarios nombrados para reemplazar ingresos y cubrir gastos después de la muerte del asegurado.', true, '2026-01-14 18:28:35.633666', '2026-01-14 18:28:35.633666') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('84f64c80-529b-4dea-8c82-b435ecb1d2db', 'life_insurance', NULL, 'What is the interest only settlement option?', '¿Qué es la opción de liquidación de solo interés?', '["The insurer holds the death benefit and pays only interest to the beneficiary", "Principal paid immediately", "No interest paid", "Monthly principal payments"]', '["El asegurador retiene el beneficio por muerte y paga solo interés al beneficiario", "Capital pagado inmediatamente", "Sin interés pagado", "Pagos mensuales de capital"]', 0, 'Interest only option holds the principal and pays interest to the beneficiary; principal can be withdrawn or paid later.', 'La opción de solo interés retiene el capital y paga interés al beneficiario; el capital puede retirarse o pagarse después.', true, '2026-01-14 22:54:57.396749', '2026-01-14 22:54:57.396749') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8517b699-5685-42c4-8fc9-0aaa57929961', 'life_insurance', NULL, 'What is a cost of living rider?', '¿Qué es un anexo de costo de vida?', '["Automatically increases coverage to keep pace with inflation", "Decreases coverage", "Fixed coverage amount", "Reduces premiums"]', '["Aumenta automáticamente la cobertura para mantener el ritmo con la inflación", "Disminuye la cobertura", "Cantidad de cobertura fija", "Reduce las primas"]', 0, 'A cost of living rider increases the death benefit periodically based on inflation or cost of living index.', 'Un anexo de costo de vida aumenta el beneficio por muerte periódicamente basándose en la inflación o índice de costo de vida.', true, '2026-01-14 22:54:57.358926', '2026-01-14 22:54:57.358926') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('864a1086-daa7-40db-bb98-a4456a428a99', 'life_insurance', NULL, 'What is modified whole life insurance?', '¿Qué es el seguro de vida entera modificado?', '["Whole life with lower premiums initially that increase after a set period", "Standard whole life", "Term insurance", "Variable life"]', '["Vida entera con primas más bajas inicialmente que aumentan después de un período establecido", "Vida entera estándar", "Seguro a término", "Vida variable"]', 0, 'Modified whole life has lower initial premiums that increase after a specified period.', 'La vida entera modificada tiene primas iniciales más bajas que aumentan después de un período especificado.', true, '2026-01-14 22:54:57.286247', '2026-01-14 22:54:57.286247') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('87c7d020-231c-464c-b7d2-c0a47cdf9d3b', 'life_insurance', NULL, 'What is a guaranteed insurability rider?', '¿Qué es un anexo de asegurabilidad garantizada?', '["A rider that reduces premiums", "A rider allowing purchase of additional coverage without evidence of insurability", "A rider that pays dividends", "A rider for accidental death"]', '["Un anexo que reduce las primas", "Un anexo que permite la compra de cobertura adicional sin evidencia de asegurabilidad", "Un anexo que paga dividendos", "Un anexo para muerte accidental"]', 1, 'A guaranteed insurability rider allows the policyholder to purchase additional coverage at specified dates without proving insurability.', 'Un anexo de asegurabilidad garantizada permite al titular de la póliza comprar cobertura adicional en fechas específicas sin probar asegurabilidad.', true, '2026-01-14 23:06:37.549108', '2026-01-14 23:06:37.549108') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('889c3394-8261-4812-ac01-0d90d0b85c3f', 'life_insurance', NULL, 'What is an annuity?', '¿Qué es una anualidad?', '["A contract that provides regular income payments, typically for retirement", "A death benefit only product", "Health insurance", "Property insurance"]', '["Un contrato que proporciona pagos de ingreso regulares, típicamente para jubilación", "Un producto solo de beneficio por muerte", "Seguro de salud", "Seguro de propiedad"]', 0, 'An annuity is a contract with an insurer that provides periodic payments, often used for retirement income.', 'Una anualidad es un contrato con un asegurador que proporciona pagos periódicos, a menudo usado para ingreso de jubilación.', true, '2026-01-14 22:54:57.424363', '2026-01-14 22:54:57.424363') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('88aba305-aa7e-405e-8d03-07d4d7279540', 'life_insurance', NULL, 'What is the purpose of a conditional receipt in life insurance?', '¿Cuál es el propósito de un recibo condicional en el seguro de vida?', '["To deny coverage", "To provide temporary coverage while the application is being processed", "To cancel the policy", "To increase premiums"]', '["Denegar cobertura", "Proporcionar cobertura temporal mientras se procesa la solicitud", "Cancelar la póliza", "Aumentar las primas"]', 1, 'A conditional receipt provides temporary coverage beginning from the date of application, subject to the applicant meeting insurability requirements.', 'Un recibo condicional proporciona cobertura temporal comenzando desde la fecha de solicitud, sujeto a que el solicitante cumpla con los requisitos de asegurabilidad.', true, '2026-01-14 23:06:37.600961', '2026-01-14 23:06:37.600961') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('897aae46-3189-48ca-8aaa-0a87d97f21a7', 'life_insurance', NULL, 'What is variable life insurance?', '¿Qué es el seguro de vida variable?', '["Life insurance where cash value is invested in securities with variable returns", "Fixed return insurance", "Term insurance", "Health insurance"]', '["Seguro de vida donde el valor en efectivo se invierte en valores con rendimientos variables", "Seguro de rendimiento fijo", "Seguro a término", "Seguro de salud"]', 0, 'Variable life allows the policyholder to invest cash value in securities, with death benefit and cash value varying based on investment performance.', 'La vida variable permite al asegurado invertir el valor en efectivo en valores, con beneficio por muerte y valor en efectivo que varían según el rendimiento de la inversión.', true, '2026-01-14 22:54:57.231324', '2026-01-14 22:54:57.231324') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8baf7794-030e-4937-921d-7b62043fc3dc', 'life_insurance', NULL, 'Under Texas law, what is the maximum period for a life insurance policy''s suicide exclusion clause?', 'Según la ley de Texas, ¿cuál es el período máximo para la cláusula de exclusión por suicidio de una póliza de seguro de vida?', '["1 year", "2 years", "3 years", "5 years"]', '["1 año", "2 años", "3 años", "5 años"]', 1, 'Texas Insurance Code limits the suicide exclusion period to a maximum of 2 years from the policy issue date.', 'El Código de Seguros de Texas limita el período de exclusión por suicidio a un máximo de 2 años desde la fecha de emisión de la póliza.', true, '2026-01-14 23:06:37.428759', '2026-01-14 23:06:37.428759') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8d1e2c0c-e941-4665-98e7-0e7d190dfaa0', 'life_insurance', NULL, 'What is underwriting in life insurance?', '¿Qué es la suscripción en el seguro de vida?', '["The process of evaluating risk and determining if coverage should be issued", "Selling policies", "Paying claims", "Collecting premiums"]', '["El proceso de evaluar riesgo y determinar si debe emitirse cobertura", "Vender pólizas", "Pagar reclamos", "Cobrar primas"]', 0, 'Underwriting evaluates the risk of insuring an applicant and determines premium rates or if coverage should be offered.', 'La suscripción evalúa el riesgo de asegurar a un solicitante y determina las tarifas de prima o si debe ofrecerse cobertura.', true, '2026-01-14 22:54:57.362485', '2026-01-14 22:54:57.362485') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8e6d9757-3c76-4ea1-863f-daea5a4c5c09', 'life_insurance', NULL, 'What is a mortality table?', '¿Qué es una tabla de mortalidad?', '["A statistical chart showing death rates at each age", "A premium chart", "A coverage table", "A claims record"]', '["Un gráfico estadístico que muestra tasas de muerte a cada edad", "Un gráfico de primas", "Una tabla de cobertura", "Un registro de reclamos"]', 0, 'Mortality tables show the probability of death at each age, used to calculate life insurance premiums.', 'Las tablas de mortalidad muestran la probabilidad de muerte a cada edad, usadas para calcular primas de seguro de vida.', true, '2026-01-14 23:01:15.757353', '2026-01-14 23:01:15.757353') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8fe0c47b-7dc1-42e9-897b-9cf66577148b', 'life_insurance', NULL, 'What is level term life insurance?', '¿Qué es el seguro de vida a término nivelado?', '["Term insurance with a death benefit that remains constant throughout the term", "Decreasing coverage", "Increasing coverage", "Variable coverage"]', '["Seguro a término con un beneficio por muerte que permanece constante durante todo el término", "Cobertura decreciente", "Cobertura creciente", "Cobertura variable"]', 0, 'Level term provides a constant death benefit and typically level premiums for the entire term.', 'El término nivelado proporciona un beneficio por muerte constante y típicamente primas niveladas durante todo el término.', true, '2026-01-14 22:54:57.261876', '2026-01-14 22:54:57.261876') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('905e8090-f19a-4561-88af-a3ff0a8478f0', 'life_insurance', NULL, 'What happens when a universal life insurance policy lapses due to insufficient cash value?', '¿Qué sucede cuando una póliza de seguro de vida universal vence debido a un valor en efectivo insuficiente?', '["The policy continues indefinitely", "Coverage terminates", "The death benefit increases", "Premiums are waived"]', '["La póliza continúa indefinidamente", "La cobertura termina", "El beneficio por muerte aumenta", "Las primas son eximidas"]', 1, 'When a universal life policy has insufficient cash value to cover the cost of insurance, the policy lapses and coverage terminates.', 'Cuando una póliza de vida universal tiene un valor en efectivo insuficiente para cubrir el costo del seguro, la póliza vence y la cobertura termina.', true, '2026-01-14 23:06:37.634319', '2026-01-14 23:06:37.634319') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('933135e4-0745-4aa1-a91a-169ee31f55e6', 'life_insurance', NULL, 'What is an annuity?', '¿Qué es una anualidad?', '["A financial product that provides regular income payments, often for retirement", "Life insurance", "Health insurance", "Property insurance"]', '["Un producto financiero que proporciona pagos de ingreso regulares, a menudo para jubilación", "Seguro de vida", "Seguro de salud", "Seguro de propiedad"]', 0, 'An annuity is a contract with an insurance company that provides regular income payments in exchange for premium payments.', 'Una anualidad es un contrato con una compañía de seguros que proporciona pagos de ingreso regulares a cambio de pagos de primas.', true, '2026-01-14 18:28:35.645443', '2026-01-14 18:28:35.645443') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('933a864a-a187-4fc5-afbc-eb9b3689fb9e', 'life_insurance', NULL, 'What is a certificate of insurance in group life?', '¿Qué es un certificado de seguro en vida grupal?', '["A document given to each group member summarizing their coverage", "The master policy", "The application", "A claim form"]', '["Un documento dado a cada miembro del grupo resumiendo su cobertura", "La póliza maestra", "La solicitud", "Un formulario de reclamo"]', 0, 'A certificate of insurance is given to each covered employee describing their coverage under the group policy.', 'Un certificado de seguro se da a cada empleado cubierto describiendo su cobertura bajo la póliza grupal.', true, '2026-01-14 22:54:57.466556', '2026-01-14 22:54:57.466556') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('961e5253-c8ec-4599-9160-f6ec9506fd36', 'life_insurance', NULL, 'What is the accumulate at interest dividend option?', '¿Qué es la opción de dividendos de acumular a interés?', '["Dividends are left with the insurer to accumulate interest", "Paid out immediately", "Used to buy insurance", "Applied to premiums"]', '["Los dividendos se dejan con el asegurador para acumular interés", "Pagados inmediatamente", "Usados para comprar seguro", "Aplicados a primas"]', 0, 'Accumulate at interest leaves dividends with the insurer where they earn interest.', 'Acumular a interés deja los dividendos con el asegurador donde ganan interés.', true, '2026-01-14 23:01:15.646376', '2026-01-14 23:01:15.646376') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('96853099-b0ce-442c-8ce6-021193ef7c43', 'life_insurance', NULL, 'What is the taxation treatment of life insurance death benefits paid to a beneficiary?', '¿Cuál es el tratamiento fiscal de los beneficios por muerte del seguro de vida pagados a un beneficiario?', '["Fully taxable as ordinary income", "Generally received income tax-free", "Taxed at capital gains rates", "Subject to 50% tax"]', '["Totalmente imponible como ingreso ordinario", "Generalmente recibido libre de impuestos sobre la renta", "Gravado a tasas de ganancias de capital", "Sujeto a impuesto del 50%"]', 1, 'Life insurance death benefits are generally received income tax-free by beneficiaries under federal tax law.', 'Los beneficios por muerte del seguro de vida generalmente se reciben libres de impuestos sobre la renta por los beneficiarios según la ley fiscal federal.', true, '2026-01-14 23:06:37.561021', '2026-01-14 23:06:37.561021') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('974ac8c7-32cb-47b9-8c65-9fbef46d4f9b', 'life_insurance', NULL, 'What is universal life insurance?', '¿Qué es el seguro de vida universal?', '["Flexible permanent insurance with adjustable premiums and death benefits", "Term insurance only", "Whole life only", "Health insurance"]', '["Seguro permanente flexible con primas y beneficios por muerte ajustables", "Solo seguro a término", "Solo vida entera", "Seguro de salud"]', 0, 'Universal life offers flexibility in premium payments and death benefits while building cash value.', 'La vida universal ofrece flexibilidad en pagos de primas y beneficios por muerte mientras acumula valor en efectivo.', true, '2026-01-14 22:54:57.227333', '2026-01-14 22:54:57.227333') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('97b9dc6e-303a-4acd-884c-d75345e3257f', 'life_insurance', NULL, 'What is the Texas Life and Health Insurance Guaranty Association?', '¿Qué es la Asociación de Garantía de Seguros de Vida y Salud de Texas?', '["An organization that protects policyholders if an insurer becomes insolvent", "A marketing organization", "A federal agency", "An insurance company"]', '["Una organización que protege a los asegurados si un asegurador se vuelve insolvente", "Una organización de marketing", "Una agencia federal", "Una compañía de seguros"]', 0, 'The Guaranty Association provides protection to policyholders if their insurance company becomes financially insolvent.', 'La Asociación de Garantía proporciona protección a los asegurados si su compañía de seguros se vuelve financieramente insolvente.', true, '2026-01-14 22:54:57.204785', '2026-01-14 22:54:57.204785') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('97d95992-7d77-4801-9523-1b9ee5833df3', 'life_insurance', NULL, 'What is a preferred risk classification?', '¿Qué es una clasificación de riesgo preferido?', '["A rating for applicants who are healthier than average and pose lower risk", "Average risk", "High risk", "Uninsurable"]', '["Una calificación para solicitantes que son más saludables que el promedio y representan menor riesgo", "Riesgo promedio", "Alto riesgo", "No asegurable"]', 0, 'Preferred risk classification is for applicants in excellent health who qualify for lower premiums.', 'La clasificación de riesgo preferido es para solicitantes en excelente salud que califican para primas más bajas.', true, '2026-01-14 22:54:57.366228', '2026-01-14 22:54:57.366228') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('981be4f1-9a4f-470f-b608-934580f78bbc', 'life_insurance', NULL, 'What is the waiver of premium rider?', '¿Qué es el anexo de exención de prima?', '["Waives premium payments if the insured becomes disabled", "Increases premiums", "Decreases death benefit", "Adds cash value"]', '["Exime los pagos de prima si el asegurado queda discapacitado", "Aumenta las primas", "Disminuye el beneficio por muerte", "Agrega valor en efectivo"]', 0, 'The waiver of premium rider pays premiums if the insured becomes totally disabled.', 'El anexo de exención de prima paga las primas si el asegurado queda totalmente discapacitado.', true, '2026-01-14 22:54:57.342427', '2026-01-14 22:54:57.342427') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9cdc1b15-6f5d-46d4-9926-8552f1dd45d4', 'life_insurance', NULL, 'What is group life insurance?', '¿Qué es el seguro de vida grupal?', '["Life insurance covering multiple people under one master policy", "Individual policies", "Health insurance", "Property insurance"]', '["Seguro de vida que cubre múltiples personas bajo una póliza maestra", "Pólizas individuales", "Seguro de salud", "Seguro de propiedad"]', 0, 'Group life insurance provides coverage to a group of people, typically employees, under a single master policy.', 'El seguro de vida grupal proporciona cobertura a un grupo de personas, típicamente empleados, bajo una única póliza maestra.', true, '2026-01-14 22:54:57.460816', '2026-01-14 22:54:57.460816') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9d1fcf84-d9fc-4c94-91b4-eedaffff9efa', 'life_insurance', NULL, 'What is a deferred annuity?', '¿Qué es una anualidad diferida?', '["An annuity where payments are delayed until a future date", "Immediate payments", "No accumulation period", "Term insurance"]', '["Una anualidad donde los pagos se retrasan hasta una fecha futura", "Pagos inmediatos", "Sin período de acumulación", "Seguro a término"]', 0, 'A deferred annuity delays income payments to a future date while funds accumulate tax-deferred.', 'Una anualidad diferida retrasa los pagos de ingreso a una fecha futura mientras los fondos se acumulan con impuestos diferidos.', true, '2026-01-14 22:54:57.437047', '2026-01-14 22:54:57.437047') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9d20d823-f4bb-433f-82a6-f9eb505a14ea', 'life_insurance', NULL, 'Are life insurance death benefits generally taxable as income?', '¿Son los beneficios por muerte del seguro de vida generalmente gravables como ingresos?', '["No, death benefits are generally received income tax-free", "Yes, fully taxable", "Partially taxable", "Taxed as capital gains"]', '["No, los beneficios por muerte generalmente se reciben libres de impuestos sobre la renta", "Sí, totalmente gravables", "Parcialmente gravables", "Gravados como ganancias de capital"]', 0, 'Life insurance death benefits are generally received by beneficiaries free of federal income tax.', 'Los beneficios por muerte del seguro de vida generalmente son recibidos por los beneficiarios libres de impuestos federales sobre la renta.', true, '2026-01-14 22:54:57.471732', '2026-01-14 22:54:57.471732') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9db39d85-23a8-4d2d-8122-791e5554a366', 'life_insurance', NULL, 'What is the needs approach to life insurance?', '¿Qué es el enfoque de necesidades para el seguro de vida?', '["Calculating coverage based on specific financial needs like debts, education, and income replacement", "Human life value only", "Minimum coverage", "Maximum coverage"]', '["Calcular cobertura basándose en necesidades financieras específicas como deudas, educación y reemplazo de ingreso", "Solo valor de vida humana", "Cobertura mínima", "Cobertura máxima"]', 0, 'The needs approach calculates coverage by adding up specific financial needs survivors would have.', 'El enfoque de necesidades calcula la cobertura sumando las necesidades financieras específicas que tendrían los sobrevivientes.', true, '2026-01-14 23:01:15.727981', '2026-01-14 23:01:15.727981') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9e8e8166-a565-445d-9fab-f9c93ac74cba', 'life_insurance', NULL, 'What is a survivorship life insurance policy (second-to-die)?', '¿Qué es una póliza de seguro de vida de sobrevivencia (segundo en morir)?', '["Pays when the first insured dies", "Pays when the last of two or more insureds dies", "Pays immediately upon purchase", "A term policy only"]', '["Paga cuando muere el primer asegurado", "Paga cuando muere el último de dos o más asegurados", "Paga inmediatamente al comprar", "Solo una póliza a término"]', 1, 'A survivorship policy covers two or more people and pays the death benefit only after the last surviving insured dies.', 'Una póliza de sobrevivencia cubre a dos o más personas y paga el beneficio por muerte solo después de que muere el último asegurado sobreviviente.', true, '2026-01-14 23:06:37.616739', '2026-01-14 23:06:37.616739') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a306a8a8-ff89-4404-b92a-bf7ea5733234', 'life_insurance', NULL, 'What is the payor benefit rider?', '¿Qué es el anexo de beneficio del pagador?', '["Waives premiums on a juvenile policy if the adult paying premiums dies or becomes disabled", "Increases death benefit", "Reduces coverage", "Changes beneficiary"]', '["Exime primas en una póliza juvenil si el adulto que paga las primas fallece o queda discapacitado", "Aumenta el beneficio por muerte", "Reduce la cobertura", "Cambia el beneficiario"]', 0, 'The payor benefit rider waives premiums on a child''s policy if the premium-paying adult dies or is disabled.', 'El anexo de beneficio del pagador exime las primas en la póliza de un niño si el adulto que paga las primas fallece o queda discapacitado.', true, '2026-01-14 23:01:15.602171', '2026-01-14 23:01:15.602171') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a483d177-0bc4-4c25-8faf-4cc89c2f5912', 'life_insurance', NULL, 'What is a hazardous occupation rider?', '¿Qué es un anexo de ocupación peligrosa?', '["Modifies coverage or premium for high-risk occupations", "Provides extra coverage", "Reduces all premiums", "Cancels the policy"]', '["Modifica cobertura o prima para ocupaciones de alto riesgo", "Proporciona cobertura extra", "Reduce todas las primas", "Cancela la póliza"]', 0, 'A hazardous occupation rider adjusts coverage terms for insureds in dangerous jobs.', 'Un anexo de ocupación peligrosa ajusta los términos de cobertura para asegurados en trabajos peligrosos.', true, '2026-01-14 23:01:15.59813', '2026-01-14 23:01:15.59813') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a5838474-3d4c-4f5e-8bcd-4f5d3665b511', 'life_insurance', NULL, 'What is indexed universal life insurance?', '¿Qué es el seguro de vida universal indexado?', '["Universal life with cash value growth tied to a stock market index", "Fixed rate insurance", "Variable life insurance", "Term insurance"]', '["Vida universal con crecimiento de valor en efectivo vinculado a un índice bursátil", "Seguro de tasa fija", "Seguro de vida variable", "Seguro a término"]', 0, 'Indexed universal life ties cash value growth to a stock market index while providing downside protection.', 'La vida universal indexada vincula el crecimiento del valor en efectivo a un índice bursátil mientras proporciona protección contra pérdidas.', true, '2026-01-14 22:54:57.244467', '2026-01-14 22:54:57.244467') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a8aba55e-0f74-4615-bd9c-7de33e23d0d6', 'life_insurance', NULL, 'What is an irrevocable life insurance trust (ILIT)?', '¿Qué es un fideicomiso de seguro de vida irrevocable (ILIT)?', '["A trust that owns life insurance to remove it from the insured''s estate", "A revocable trust", "A bank account", "A checking account"]', '["Un fideicomiso que posee seguro de vida para removerlo del patrimonio del asegurado", "Un fideicomiso revocable", "Una cuenta bancaria", "Una cuenta de cheques"]', 0, 'An ILIT owns a life insurance policy so the death benefit is not included in the insured''s taxable estate.', 'Un ILIT posee una póliza de seguro de vida para que el beneficio por muerte no se incluya en el patrimonio gravable del asegurado.', true, '2026-01-14 23:01:15.749735', '2026-01-14 23:01:15.749735') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ab5cb65e-c59d-4ff3-9481-8e1798d737b2', 'life_insurance', NULL, 'What is nonforfeiture in life insurance?', '¿Qué es la no caducidad en el seguro de vida?', '["Options that allow policyholders to retain some value if they stop paying premiums", "Forfeiting all value", "Automatic cancellation", "Premium refund only"]', '["Opciones que permiten a los asegurados retener algún valor si dejan de pagar primas", "Perder todo el valor", "Cancelación automática", "Solo reembolso de prima"]', 0, 'Nonforfeiture options protect the policyholder''s cash value if they can no longer pay premiums.', 'Las opciones de no caducidad protegen el valor en efectivo del asegurado si ya no puede pagar las primas.', true, '2026-01-14 23:01:15.538193', '2026-01-14 23:01:15.538193') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ad9f637f-f217-465b-a1df-289894a117df', 'life_insurance', NULL, 'What is reduced paid-up insurance as a nonforfeiture option?', '¿Qué es el seguro reducido pagado como opción de no caducidad?', '["Using cash value to purchase a smaller permanent policy with no future premiums", "Extended term", "Cash surrender", "Premium refund"]', '["Usar el valor en efectivo para comprar una póliza permanente más pequeña sin primas futuras", "Término extendido", "Rescate en efectivo", "Reembolso de prima"]', 0, 'Reduced paid-up uses cash value to purchase a smaller permanent policy that remains in force without future premiums.', 'El seguro reducido pagado usa el valor en efectivo para comprar una póliza permanente más pequeña que permanece en vigor sin primas futuras.', true, '2026-01-14 23:01:15.553652', '2026-01-14 23:01:15.553652') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('adb9ec73-4c51-467e-9119-fa6ee9437ae3', 'life_insurance', NULL, 'What is the life income settlement option?', '¿Qué es la opción de liquidación de ingreso vitalicio?', '["Payments made for the beneficiary''s lifetime", "Fixed period payments", "Lump sum", "Interest only"]', '["Pagos hechos por la vida del beneficiario", "Pagos de período fijo", "Suma global", "Solo interés"]', 0, 'Life income settlement provides payments to the beneficiary for their entire life based on the death benefit.', 'La liquidación de ingreso vitalicio proporciona pagos al beneficiario por toda su vida basándose en el beneficio por muerte.', true, '2026-01-14 22:54:57.410329', '2026-01-14 22:54:57.410329') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('adef0823-56a9-4013-bc3f-912d3ceadf9d', 'life_insurance', NULL, 'What is limited pay life insurance?', '¿Qué es el seguro de vida de pago limitado?', '["Permanent insurance where premiums are paid for a limited period but coverage continues for life", "Term insurance", "Single premium", "Monthly payments forever"]', '["Seguro permanente donde las primas se pagan por un período limitado pero la cobertura continúa de por vida", "Seguro a término", "Prima única", "Pagos mensuales para siempre"]', 0, 'Limited pay provides permanent coverage but premiums are paid over a shorter period (like 10 or 20 years).', 'El pago limitado proporciona cobertura permanente pero las primas se pagan durante un período más corto (como 10 o 20 años).', true, '2026-01-14 22:54:57.282396', '2026-01-14 22:54:57.282396') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('aeadc7da-5ff7-4de5-a784-51b79d0f1eca', 'life_insurance', NULL, 'What is the purpose of the payor benefit rider in life insurance?', '¿Cuál es el propósito del anexo de beneficio del pagador en el seguro de vida?', '["To pay additional death benefits", "To waive premiums if the premium payer dies or becomes disabled", "To add additional insureds", "To increase cash value"]', '["Pagar beneficios adicionales por muerte", "Eximir las primas si el pagador de la prima muere o queda discapacitado", "Agregar asegurados adicionales", "Aumentar el valor en efectivo"]', 1, 'The payor benefit rider waives future premiums on a juvenile policy if the premium payer (usually a parent) dies or becomes disabled.', 'El anexo de beneficio del pagador exime las primas futuras de una póliza juvenil si el pagador de la prima (generalmente un padre) muere o queda discapacitado.', true, '2026-01-14 23:06:37.522227', '2026-01-14 23:06:37.522227') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('af9c30da-5724-43e2-bca7-f70f4a83047b', 'life_insurance', NULL, 'What is chronic illness rider?', '¿Qué es un anexo de enfermedad crónica?', '["Allows early access to death benefit if diagnosed with a chronic illness", "Terminal illness only", "No access to benefits", "Increases premium"]', '["Permite acceso anticipado al beneficio por muerte si se diagnostica una enfermedad crónica", "Solo enfermedad terminal", "Sin acceso a beneficios", "Aumenta la prima"]', 0, 'A chronic illness rider allows the insured to access death benefits if they''re diagnosed with a chronic illness.', 'Un anexo de enfermedad crónica permite al asegurado acceder a beneficios por muerte si se le diagnostica una enfermedad crónica.', true, '2026-01-14 23:01:15.617084', '2026-01-14 23:01:15.617084') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b0380894-6a57-4615-9757-133acdaf7b85', 'life_insurance', NULL, 'What is the purpose of the life insurance policy''s reinstatement provision?', '¿Cuál es el propósito de la disposición de reinstalación de la póliza de seguro de vida?', '["To cancel the policy", "To allow revival of a lapsed policy under certain conditions", "To change beneficiaries", "To reduce the face amount"]', '["Cancelar la póliza", "Permitir la reactivación de una póliza vencida bajo ciertas condiciones", "Cambiar beneficiarios", "Reducir el monto nominal"]', 1, 'The reinstatement provision allows a policyholder to revive a lapsed policy within a certain timeframe by paying back premiums and providing evidence of insurability.', 'La disposición de reinstalación permite a un titular de póliza reactivar una póliza vencida dentro de un cierto período de tiempo pagando las primas atrasadas y proporcionando evidencia de asegurabilidad.', true, '2026-01-14 23:06:37.508715', '2026-01-14 23:06:37.508715') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b0b37b85-7189-444d-917a-da925d2e92e0', 'life_insurance', NULL, 'What is the purpose of the Medical Information Bureau (MIB) in life insurance underwriting?', '¿Cuál es el propósito de la Oficina de Información Médica (MIB) en la suscripción de seguros de vida?', '["To provide medical treatment", "To share medical underwriting information between insurers", "To set premium rates", "To issue policies"]', '["Proporcionar tratamiento médico", "Compartir información de suscripción médica entre aseguradoras", "Establecer tasas de primas", "Emitir pólizas"]', 1, 'The MIB is a database that allows insurance companies to share medical underwriting information to prevent fraud and assess risk.', 'El MIB es una base de datos que permite a las compañías de seguros compartir información de suscripción médica para prevenir fraudes y evaluar riesgos.', true, '2026-01-14 23:06:37.461542', '2026-01-14 23:06:37.461542') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b0dd4dbf-778f-4915-a2d1-60d8197ed19d', 'life_insurance', NULL, 'What is the accumulation period of an annuity?', '¿Qué es el período de acumulación de una anualidad?', '["The time during which premiums are paid and funds grow", "The payout period", "The surrender period", "The free-look period"]', '["El tiempo durante el cual se pagan las primas y los fondos crecen", "El período de pago", "El período de rescate", "El período de revisión gratuita"]', 0, 'The accumulation period is when premiums are paid and the annuity value grows tax-deferred.', 'El período de acumulación es cuando se pagan las primas y el valor de la anualidad crece con impuestos diferidos.', true, '2026-01-14 22:54:57.446145', '2026-01-14 22:54:57.446145') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b1c733ad-d574-4a52-b891-03fced2cdc8c', 'life_insurance', NULL, 'What is the continuing education requirement for Texas life insurance license renewal?', '¿Cuál es el requisito de educación continua para la renovación de licencia de seguro de vida de Texas?', '["24 hours including ethics", "12 hours", "40 hours", "No CE required"]', '["24 horas incluyendo ética", "12 horas", "40 horas", "No se requiere EC"]', 0, 'Texas requires 24 hours of continuing education for license renewal, including ethics hours.', 'Texas requiere 24 horas de educación continua para la renovación de licencia, incluyendo horas de ética.', true, '2026-01-14 22:54:57.194745', '2026-01-14 22:54:57.194745') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b3424594-4156-44ba-bdaa-6e7a1a94d3f1', 'life_insurance', NULL, 'What is family income policy?', '¿Qué es una póliza de ingreso familiar?', '["Combines whole life with decreasing term to provide income for a period after death", "Term only", "Whole life only", "Variable life"]', '["Combina vida entera con término decreciente para proporcionar ingreso por un período después de la muerte", "Solo término", "Solo vida entera", "Vida variable"]', 0, 'A family income policy provides monthly income to survivors for a specified period, plus a lump-sum death benefit.', 'Una póliza de ingreso familiar proporciona ingreso mensual a los sobrevivientes por un período especificado, más un beneficio por muerte de suma global.', true, '2026-01-14 23:01:15.693449', '2026-01-14 23:01:15.693449') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b34cd67f-62f2-462d-a9fa-2e6dc2474e97', 'life_insurance', NULL, 'What is a substandard (rated) risk classification?', '¿Qué es una clasificación de riesgo subestándar (calificado)?', '["A rating for applicants with higher-than-average risk who pay higher premiums", "Best risk", "Standard risk", "Uninsurable"]', '["Una calificación para solicitantes con riesgo más alto que el promedio que pagan primas más altas", "Mejor riesgo", "Riesgo estándar", "No asegurable"]', 0, 'Substandard (rated) risks have health conditions requiring higher premiums due to increased mortality risk.', 'Los riesgos subestándar (calificados) tienen condiciones de salud que requieren primas más altas debido al mayor riesgo de mortalidad.', true, '2026-01-14 22:54:57.377876', '2026-01-14 22:54:57.377876') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b470a26d-d9f3-4425-9426-dbc9da0b6e92', 'life_insurance', NULL, 'What is an entity (stock redemption) buy-sell agreement?', '¿Qué es un acuerdo de compra-venta de entidad (redención de acciones)?', '["The business itself owns policies on the owners and buys back shares upon death", "Owners insure each other", "No insurance used", "Bank purchases shares"]', '["El negocio mismo posee pólizas sobre los propietarios y recompra acciones al fallecer", "Los propietarios aseguran a cada uno", "Sin seguro usado", "El banco compra acciones"]', 0, 'In entity agreements, the business owns policies on each owner and uses proceeds to redeem a deceased owner''s shares.', 'En acuerdos de entidad, el negocio posee pólizas sobre cada propietario y usa los beneficios para redimir las acciones de un propietario fallecido.', true, '2026-01-14 22:54:57.493466', '2026-01-14 22:54:57.493466') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b6edb908-5c3d-466a-a933-12ed5b6892bf', 'life_insurance', NULL, 'What is the purpose of a life settlement?', '¿Cuál es el propósito de un acuerdo de vida?', '["To cancel a policy", "To sell a life insurance policy for more than its cash value but less than the death benefit", "To change beneficiaries", "To reduce coverage"]', '["Cancelar una póliza", "Vender una póliza de seguro de vida por más de su valor en efectivo pero menos del beneficio por muerte", "Cambiar beneficiarios", "Reducir la cobertura"]', 1, 'A life settlement is the sale of an existing life insurance policy to a third party for more than the cash surrender value but less than the face amount.', 'Un acuerdo de vida es la venta de una póliza de seguro de vida existente a un tercero por más del valor de rescate en efectivo pero menos del monto nominal.', true, '2026-01-14 23:06:37.541356', '2026-01-14 23:06:37.541356') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b8693cc8-5ea2-4956-a57d-112b578572b6', 'life_insurance', NULL, 'What is an exclusion ratio in annuities?', '¿Qué es un índice de exclusión en anualidades?', '["The portion of each annuity payment that is tax-free return of principal", "Full taxation", "No taxation", "Capital gains rate"]', '["La porción de cada pago de anualidad que es devolución de capital libre de impuestos", "Tributación completa", "Sin tributación", "Tasa de ganancias de capital"]', 0, 'The exclusion ratio determines how much of each annuity payment is return of premium (tax-free) vs. taxable gain.', 'El índice de exclusión determina cuánto de cada pago de anualidad es devolución de prima (libre de impuestos) vs. ganancia gravable.', true, '2026-01-14 23:01:15.765566', '2026-01-14 23:01:15.765566') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b9897cd5-d0ed-415b-9f94-c245e0d9d16b', 'life_insurance', NULL, 'What is a 1035 exchange?', '¿Qué es un intercambio 1035?', '["Tax-free exchange of one life insurance or annuity for another", "Taxable exchange", "Premium payment", "Policy loan"]', '["Intercambio libre de impuestos de un seguro de vida o anualidad por otro", "Intercambio gravable", "Pago de prima", "Préstamo de póliza"]', 0, 'A 1035 exchange allows tax-free transfer of values from one life insurance policy or annuity to another.', 'Un intercambio 1035 permite transferencia libre de impuestos de valores de una póliza de seguro de vida o anualidad a otra.', true, '2026-01-14 23:01:15.737043', '2026-01-14 23:01:15.737043') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ba2286d3-fcea-42ed-a1f2-36bde6884588', 'life_insurance', NULL, 'What dividend option uses dividends to purchase additional paid-up insurance?', '¿Qué opción de dividendos usa los dividendos para comprar seguro pagado adicional?', '["Paid-up additions", "Cash payment", "Premium reduction", "Accumulate at interest"]', '["Adiciones pagadas", "Pago en efectivo", "Reducción de prima", "Acumular a interés"]', 0, 'Paid-up additions use dividends to purchase additional fully paid permanent insurance.', 'Las adiciones pagadas usan dividendos para comprar seguro permanente totalmente pagado adicional.', true, '2026-01-14 23:01:15.64002', '2026-01-14 23:01:15.64002') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('baf21d85-d5c8-43d4-9f1b-5791cbdd5097', 'life_insurance', NULL, 'What is graded premium whole life insurance?', '¿Qué es el seguro de vida entera de prima graduada?', '["Whole life with premiums that start low and gradually increase to a level amount", "Level premium whole life", "Term insurance", "Variable life"]', '["Vida entera con primas que comienzan bajas y aumentan gradualmente a una cantidad nivelada", "Vida entera de prima nivelada", "Seguro a término", "Vida variable"]', 0, 'Graded premium whole life has premiums that gradually increase over several years before leveling off.', 'La vida entera de prima graduada tiene primas que aumentan gradualmente durante varios años antes de nivelarse.', true, '2026-01-14 22:54:57.291208', '2026-01-14 22:54:57.291208') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bc16c3e2-22e8-4183-81e0-c0b87d44d2cd', 'life_insurance', NULL, 'What is the misstatement of age or sex provision?', '¿Qué es la disposición de declaración errónea de edad o sexo?', '["If age or sex was misstated, the death benefit is adjusted to what premiums would have purchased", "Policy is voided", "No adjustment is made", "Premium is refunded"]', '["Si la edad o sexo fue declarado erróneamente, el beneficio por muerte se ajusta a lo que las primas habrían comprado", "La póliza se anula", "No se hace ajuste", "Se reembolsa la prima"]', 0, 'This provision adjusts the death benefit based on the correct age or sex rather than voiding the policy.', 'Esta disposición ajusta el beneficio por muerte basándose en la edad o sexo correctos en lugar de anular la póliza.', true, '2026-01-14 22:54:57.316625', '2026-01-14 22:54:57.316625') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bc9e4a66-9ad2-4917-ac45-b1ead51914b3', 'life_insurance', NULL, 'What is the contestability period?', '¿Qué es el período de contestabilidad?', '["The period (usually 2 years) during which the insurer can void the policy for misrepresentation", "The grace period", "The free-look period", "The policy term"]', '["El período (usualmente 2 años) durante el cual el asegurador puede anular la póliza por tergiversación", "El período de gracia", "El período de revisión gratuita", "El término de la póliza"]', 0, 'During the contestability period, the insurer can investigate and deny claims for material misrepresentation.', 'Durante el período de contestabilidad, el asegurador puede investigar y negar reclamos por tergiversación material.', true, '2026-01-14 22:54:57.30426', '2026-01-14 22:54:57.30426') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bd5122d9-e605-4c02-a695-81c97cc426dd', 'life_insurance', NULL, 'What is a beneficiary in a life insurance policy?', '¿Qué es un beneficiario en una póliza de seguro de vida?', '["The insurance company", "The person who receives the death benefit", "The policyholder", "The insurance agent"]', '["La compañía de seguros", "La persona que recibe el beneficio por fallecimiento", "El titular de la póliza", "El agente de seguros"]', 1, 'A beneficiary is the person or entity designated to receive the death benefit when the insured person dies.', 'Un beneficiario es la persona o entidad designada para recibir el beneficio por fallecimiento cuando el asegurado fallece.', true, '2026-01-14 16:50:01.908265', '2026-01-14 16:50:01.908265') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bd782827-eb53-4a9d-8eca-ad04baafa065', 'life_insurance', NULL, 'Who owns a group life insurance policy?', '¿Quién es dueño de una póliza de seguro de vida grupal?', '["The employer or group sponsor", "Each employee", "The insurance company", "The government"]', '["El empleador o patrocinador del grupo", "Cada empleado", "La compañía de seguros", "El gobierno"]', 0, 'The employer or sponsoring organization owns the master policy and provides certificates to employees.', 'El empleador u organización patrocinadora es dueño de la póliza maestra y proporciona certificados a los empleados.', true, '2026-01-14 22:54:57.463614', '2026-01-14 22:54:57.463614') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bf116350-ae51-4281-9aa1-2f6ccad873d5', 'life_insurance', NULL, 'What is the automatic premium loan provision?', '¿Qué es la disposición de préstamo automático de prima?', '["Automatically borrows from cash value to pay overdue premiums", "Cancels the policy", "Requires additional payment", "Reduces death benefit immediately"]', '["Toma prestado automáticamente del valor en efectivo para pagar primas vencidas", "Cancela la póliza", "Requiere pago adicional", "Reduce el beneficio por muerte inmediatamente"]', 0, 'The automatic premium loan provision uses cash value to pay premiums if the policyholder misses a payment.', 'La disposición de préstamo automático de prima usa el valor en efectivo para pagar primas si el asegurado pierde un pago.', true, '2026-01-14 23:01:15.558067', '2026-01-14 23:01:15.558067') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bff7dc82-a12e-4cc6-9dc1-a3bdb0cf753b', 'life_insurance', NULL, 'What is a refund annuity?', '¿Qué es una anualidad con reembolso?', '["Guarantees that total payments will at least equal the premium paid", "No refund available", "Lump sum only", "Life income only"]', '["Garantiza que los pagos totales al menos igualen la prima pagada", "Sin reembolso disponible", "Solo suma global", "Solo ingreso vitalicio"]', 0, 'A refund annuity guarantees that if the annuitant dies early, beneficiaries receive at least the premium paid.', 'Una anualidad con reembolso garantiza que si el beneficiario muere temprano, los beneficiarios reciben al menos la prima pagada.', true, '2026-01-14 23:01:15.784594', '2026-01-14 23:01:15.784594') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c0960afb-bfb0-424f-8fb0-2885e7ec3430', 'life_insurance', NULL, 'What happens if a policy loan is not repaid?', '¿Qué sucede si un préstamo de póliza no se paga?', '["The outstanding loan amount reduces the death benefit", "Nothing happens", "The policy continues unchanged", "The insurer pays the loan"]', '["El monto del préstamo pendiente reduce el beneficio por muerte", "No pasa nada", "La póliza continúa sin cambios", "El asegurador paga el préstamo"]', 0, 'Unpaid policy loans plus interest are deducted from the death benefit when the insured dies.', 'Los préstamos de póliza no pagados más interés se deducen del beneficio por muerte cuando el asegurado fallece.', true, '2026-01-14 22:54:57.417937', '2026-01-14 22:54:57.417937') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c2a829af-6912-465b-b2b4-a95726f1d7a7', 'life_insurance', NULL, 'What is a fixed annuity?', '¿Qué es una anualidad fija?', '["An annuity with variable payments", "An annuity that guarantees a minimum interest rate and fixed payments", "An annuity tied to the stock market", "An annuity with no guarantees"]', '["Una anualidad con pagos variables", "Una anualidad que garantiza una tasa de interés mínima y pagos fijos", "Una anualidad vinculada al mercado de valores", "Una anualidad sin garantías"]', 1, 'A fixed annuity provides a guaranteed minimum interest rate during accumulation and fixed payments during the payout phase.', 'Una anualidad fija proporciona una tasa de interés mínima garantizada durante la acumulación y pagos fijos durante la fase de pago.', true, '2026-01-14 23:06:37.564848', '2026-01-14 23:06:37.564848') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c3583c5c-07f2-4bb1-8ed6-6cca29d9d129', 'life_insurance', NULL, 'What is final expense insurance?', '¿Qué es el seguro de gastos finales?', '["Small whole life policies designed to cover funeral and burial costs", "Large death benefits", "Investment products", "Health insurance"]', '["Pólizas pequeñas de vida entera diseñadas para cubrir costos funerarios y de entierro", "Grandes beneficios por muerte", "Productos de inversión", "Seguro de salud"]', 0, 'Final expense insurance provides a small death benefit intended to cover burial, funeral, and final medical expenses.', 'El seguro de gastos finales proporciona un pequeño beneficio por muerte destinado a cubrir entierro, funeral y gastos médicos finales.', true, '2026-01-14 23:01:15.660504', '2026-01-14 23:01:15.660504') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c56d058a-b500-4069-a9be-b4e560439dd7', 'life_insurance', NULL, 'What is the purpose of a life insurance policy illustration in Texas?', '¿Cuál es el propósito de una ilustración de póliza de seguro de vida en Texas?', '["To guarantee future returns", "To show how the policy may perform under different scenarios", "To replace the policy contract", "To waive disclosure requirements"]', '["Garantizar rendimientos futuros", "Mostrar cómo puede funcionar la póliza bajo diferentes escenarios", "Reemplazar el contrato de la póliza", "Renunciar a los requisitos de divulgación"]', 1, 'Policy illustrations show hypothetical scenarios of how a policy may perform but are not guarantees of future performance.', 'Las ilustraciones de pólizas muestran escenarios hipotéticos de cómo puede funcionar una póliza pero no son garantías de rendimiento futuro.', true, '2026-01-14 23:06:37.449184', '2026-01-14 23:06:37.449184') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cd5e8442-4d51-4801-bc1a-b77899ab26e2', 'life_insurance', NULL, 'What is credit life insurance?', '¿Qué es el seguro de vida de crédito?', '["Insurance that pays off a loan balance if the borrower dies", "Investment insurance", "Health insurance", "Property insurance"]', '["Seguro que paga el saldo de un préstamo si el prestatario fallece", "Seguro de inversión", "Seguro de salud", "Seguro de propiedad"]', 0, 'Credit life insurance pays the outstanding loan balance to the lender if the borrower dies.', 'El seguro de vida de crédito paga el saldo del préstamo pendiente al prestamista si el prestatario fallece.', true, '2026-01-14 23:01:15.680317', '2026-01-14 23:01:15.680317') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ce1ffbae-2f3f-4cf3-a7d1-f00942576725', 'life_insurance', NULL, 'How many hours of pre-licensing education are required for a life insurance license in Texas?', '¿Cuántas horas de educación previa a la licencia se requieren para una licencia de seguro de vida en Texas?', '["40 hours", "20 hours", "60 hours", "80 hours"]', '["40 horas", "20 horas", "60 horas", "80 horas"]', 0, 'Texas requires 40 hours of pre-licensing education for a life insurance license.', 'Texas requiere 40 horas de educación previa a la licencia para una licencia de seguro de vida.', true, '2026-01-14 22:54:57.186486', '2026-01-14 22:54:57.186486') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cf3fb4f2-53d9-4a5d-b2da-34711717e791', 'life_insurance', NULL, 'What is a life annuity?', '¿Qué es una anualidad vitalicia?', '["An annuity that pays for the lifetime of the annuitant", "Fixed period payments", "Lump sum payment", "No guaranteed payments"]', '["Una anualidad que paga por la vida del beneficiario", "Pagos de período fijo", "Pago de suma global", "Sin pagos garantizados"]', 0, 'A life annuity provides payments for as long as the annuitant lives.', 'Una anualidad vitalicia proporciona pagos mientras el beneficiario viva.', true, '2026-01-14 22:54:57.45224', '2026-01-14 22:54:57.45224') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cf96a6cf-4f8b-413d-bae1-25f736d3b0ce', 'life_insurance', NULL, 'Who owns a juvenile life insurance policy?', '¿Quién es dueño de una póliza de seguro de vida juvenil?', '["The adult who purchased it until the child reaches a specified age", "The child from the start", "The insurance company", "The government"]', '["El adulto que la compró hasta que el niño alcance una edad especificada", "El niño desde el inicio", "La compañía de seguros", "El gobierno"]', 0, 'The adult purchaser owns the juvenile policy until ownership transfers to the child at a specified age.', 'El adulto comprador es dueño de la póliza juvenil hasta que la propiedad se transfiere al niño a una edad especificada.', true, '2026-01-14 23:01:15.71389', '2026-01-14 23:01:15.71389') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cff49d00-07d4-4d9c-8d45-fa6b61b51a1c', 'life_insurance', NULL, 'What is a spendthrift clause?', '¿Qué es una cláusula de derrochador?', '["Protects policy proceeds from creditors of the beneficiary", "Allows creditor access", "Increases death benefit", "Reduces premiums"]', '["Protege los beneficios de la póliza de los acreedores del beneficiario", "Permite acceso de acreedores", "Aumenta el beneficio por muerte", "Reduce las primas"]', 0, 'A spendthrift clause protects death benefit proceeds from claims by the beneficiary''s creditors.', 'Una cláusula de derrochador protege los beneficios por muerte de reclamos de los acreedores del beneficiario.', true, '2026-01-14 23:01:15.575914', '2026-01-14 23:01:15.575914') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d0cc6a18-f84e-43e7-8636-536371ba2bf5', 'life_insurance', NULL, 'What is the grace period in life insurance?', '¿Qué es el período de gracia en el seguro de vida?', '["A period after the premium due date during which the policy remains in force", "The free-look period", "The contestability period", "The policy term"]', '["Un período después de la fecha de vencimiento de la prima durante el cual la póliza permanece en vigor", "El período de revisión gratuita", "El período de contestabilidad", "El término de la póliza"]', 0, 'The grace period (typically 30-31 days) allows payment after the due date without policy lapse.', 'El período de gracia (típicamente 30-31 días) permite el pago después de la fecha de vencimiento sin que la póliza caduque.', true, '2026-01-14 22:54:57.299739', '2026-01-14 22:54:57.299739') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d18e6c1a-dddb-42f4-9ac3-e0ce8e573c42', 'life_insurance', NULL, 'What is cash value in life insurance?', '¿Qué es el valor en efectivo en el seguro de vida?', '["The savings component of permanent life insurance that grows over time", "The premium", "The death benefit", "The policy fee"]', '["El componente de ahorro del seguro de vida permanente que crece con el tiempo", "La prima", "El beneficio por muerte", "La tarifa de la póliza"]', 0, 'Cash value is the savings portion of permanent life insurance that accumulates on a tax-deferred basis.', 'El valor en efectivo es la porción de ahorro del seguro de vida permanente que se acumula con impuestos diferidos.', true, '2026-01-14 22:54:57.253293', '2026-01-14 22:54:57.253293') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d21faeb7-2bf7-4b08-8b65-c32e5a8a1902', 'life_insurance', NULL, 'What is a fixed annuity?', '¿Qué es una anualidad fija?', '["An annuity that guarantees a fixed interest rate and payment amount", "Variable returns", "No guaranteed payments", "Stock market returns"]', '["Una anualidad que garantiza una tasa de interés fija y monto de pago", "Rendimientos variables", "Sin pagos garantizados", "Rendimientos del mercado de valores"]', 0, 'A fixed annuity provides guaranteed interest rates and predictable payment amounts.', 'Una anualidad fija proporciona tasas de interés garantizadas y montos de pago predecibles.', true, '2026-01-14 22:54:57.427437', '2026-01-14 22:54:57.427437') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d637631f-229b-45e3-ab79-3f81e86631bd', 'life_insurance', NULL, 'What is the cost of insurance in a life insurance policy?', '¿Cuál es el costo de seguro en una póliza de seguro de vida?', '["The portion of premium that covers the mortality risk", "The full premium", "The cash value", "The death benefit"]', '["La porción de la prima que cubre el riesgo de mortalidad", "La prima completa", "El valor en efectivo", "El beneficio por muerte"]', 0, 'The cost of insurance is the mortality charge that covers the risk of paying the death benefit.', 'El costo de seguro es el cargo de mortalidad que cubre el riesgo de pagar el beneficio por muerte.', true, '2026-01-14 23:01:15.761538', '2026-01-14 23:01:15.761538') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d6f23033-223a-49a9-a364-32e9e09acf6c', 'life_insurance', NULL, 'What is a waiver of premium rider?', '¿Qué es un anexo de exención de prima?', '["A rider that waives premium payments if the insured becomes disabled", "A discount on premiums", "A type of beneficiary", "A coverage limit"]', '["Un anexo que exime pagos de prima si el asegurado queda discapacitado", "Un descuento en primas", "Un tipo de beneficiario", "Un límite de cobertura"]', 0, 'The waiver of premium rider keeps the life insurance policy in force without premium payments if the insured becomes totally disabled.', 'El anexo de exención de prima mantiene la póliza de seguro de vida en vigor sin pagos de prima si el asegurado queda totalmente discapacitado.', true, '2026-01-14 18:28:35.655907', '2026-01-14 18:28:35.655907') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d8247d86-81d1-4248-b92a-61488d4e4eb5', 'life_insurance', NULL, 'What is corporate-owned life insurance (COLI)?', '¿Qué es el seguro de vida propiedad de la corporación (COLI)?', '["Life insurance purchased and owned by a corporation on employees", "Personal insurance", "Health insurance", "Auto insurance"]', '["Seguro de vida comprado y poseído por una corporación sobre empleados", "Seguro personal", "Seguro de salud", "Seguro de auto"]', 0, 'COLI is life insurance owned by a corporation, often used for executive benefits or funding business obligations.', 'COLI es seguro de vida poseído por una corporación, a menudo usado para beneficios ejecutivos o financiar obligaciones comerciales.', true, '2026-01-14 22:54:57.49843', '2026-01-14 22:54:57.49843') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d8ebedee-d804-4397-b886-7248e5ffcb6c', 'life_insurance', NULL, 'What is the free look period?', '¿Qué es el período de revisión gratuita?', '["A period after policy delivery when you can cancel for a full refund", "The grace period", "The contestability period", "The waiting period"]', '["Un período después de la entrega de la póliza cuando puedes cancelar para un reembolso completo", "El período de gracia", "El período de contestabilidad", "El período de espera"]', 0, 'The free look period allows policyholders to review a new policy and cancel it for a full refund if not satisfied, typically 10-30 days.', 'El período de revisión gratuita permite a los asegurados revisar una nueva póliza y cancelarla para un reembolso completo si no están satisfechos, típicamente 10-30 días.', true, '2026-01-14 18:28:35.670432', '2026-01-14 18:28:35.670432') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('da4b083b-e06f-4112-82c5-8e5c6fc4a239', 'life_insurance', NULL, 'What is the face amount of a life insurance policy?', '¿Cuál es el monto nominal de una póliza de seguro de vida?', '["The death benefit payable upon the insured''s death", "The premium amount", "The cash value", "The loan amount"]', '["El beneficio por muerte pagadero al fallecer el asegurado", "El monto de la prima", "El valor en efectivo", "El monto del préstamo"]', 0, 'The face amount is the death benefit amount stated on the policy that will be paid to beneficiaries.', 'El monto nominal es la cantidad del beneficio por muerte establecida en la póliza que se pagará a los beneficiarios.', true, '2026-01-14 22:54:57.249167', '2026-01-14 22:54:57.249167') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('dbf10af0-d9e2-4f48-be15-984edfb67f8d', 'life_insurance', NULL, 'What is a life settlement?', '¿Qué es un acuerdo de vida?', '["Selling a life insurance policy to a third party, typically by seniors who no longer need coverage", "A viatical settlement for terminally ill", "A policy loan", "A claim"]', '["Vender una póliza de seguro de vida a un tercero, típicamente por personas mayores que ya no necesitan cobertura", "Un acuerdo viático para terminalmente enfermos", "Un préstamo de póliza", "Un reclamo"]', 0, 'A life settlement is similar to viatical but for seniors who simply no longer need or want their life insurance.', 'Un acuerdo de vida es similar al viático pero para personas mayores que simplemente ya no necesitan o quieren su seguro de vida.', true, '2026-01-14 22:54:57.504454', '2026-01-14 22:54:57.504454') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('dca4bd73-1e8a-4c9c-9a3b-fddedf47c4c9', 'life_insurance', NULL, 'What is guaranteed issue life insurance?', '¿Qué es el seguro de vida de emisión garantizada?', '["Life insurance issued without medical underwriting or health questions", "Full medical exam required", "Only for healthy individuals", "Variable insurance"]', '["Seguro de vida emitido sin suscripción médica o preguntas de salud", "Examen médico completo requerido", "Solo para individuos saludables", "Seguro variable"]', 0, 'Guaranteed issue policies accept all applicants without health questions, typically with limited benefits initially.', 'Las pólizas de emisión garantizada aceptan a todos los solicitantes sin preguntas de salud, típicamente con beneficios limitados inicialmente.', true, '2026-01-14 23:01:15.666207', '2026-01-14 23:01:15.666207') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('dd06f34b-0f50-41be-83f3-d9831275e8af', 'life_insurance', NULL, 'Under Texas law, what happens to a life insurance policy if the insured dies during the grace period?', 'Según la ley de Texas, ¿qué sucede con una póliza de seguro de vida si el asegurado muere durante el período de gracia?', '["The policy is void", "The claim is denied", "The death benefit is paid minus the unpaid premium", "The beneficiary must pay all back premiums"]', '["La póliza es nula", "El reclamo es denegado", "El beneficio por muerte se paga menos la prima no pagada", "El beneficiario debe pagar todas las primas atrasadas"]', 2, 'If the insured dies during the grace period, the death benefit is paid but the unpaid premium is deducted from the benefit amount.', 'Si el asegurado muere durante el período de gracia, el beneficio por muerte se paga pero la prima no pagada se deduce del monto del beneficio.', true, '2026-01-14 23:06:37.470502', '2026-01-14 23:06:37.470502') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('de64fa5d-89d1-4676-a64e-0e1f7759d992', 'life_insurance', NULL, 'What is the grace period in life insurance?', '¿Qué es el período de gracia en seguro de vida?', '["A period after the premium due date during which coverage continues", "The waiting period", "The free look period", "The contestability period"]', '["Un período después de la fecha de vencimiento de la prima durante el cual la cobertura continúa", "El período de espera", "El período de revisión gratuita", "El período de contestabilidad"]', 0, 'The grace period is typically 30-31 days after a premium due date during which the policy remains in force even if payment is late.', 'El período de gracia es típicamente 30-31 días después de la fecha de vencimiento de la prima durante los cuales la póliza permanece en vigor aunque el pago esté atrasado.', true, '2026-01-14 18:28:35.647881', '2026-01-14 18:28:35.647881') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('df1bf2da-b566-4212-98ab-f88f965c3601', 'life_insurance', NULL, 'What is an annuity period certain?', '¿Qué es una anualidad de período cierto?', '["Guarantees payments for a minimum period even if the annuitant dies", "Payments only while living", "No guaranteed payments", "Single payment only"]', '["Garantiza pagos por un período mínimo incluso si el beneficiario fallece", "Pagos solo mientras viva", "Sin pagos garantizados", "Solo pago único"]', 0, 'Period certain guarantees a minimum number of payments; if the annuitant dies early, beneficiaries receive remaining payments.', 'El período cierto garantiza un número mínimo de pagos; si el beneficiario muere temprano, los beneficiarios reciben los pagos restantes.', true, '2026-01-14 22:54:57.457756', '2026-01-14 22:54:57.457756') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('dfc1393a-a924-4bf8-a20a-f5d89c952a18', 'life_insurance', NULL, 'What is a contingent beneficiary?', '¿Qué es un beneficiario contingente?', '["The person who receives the death benefit if the primary beneficiary predeceases the insured", "The first beneficiary", "The insurance company", "The policy owner"]', '["La persona que recibe el beneficio por muerte si el beneficiario primario fallece antes que el asegurado", "El primer beneficiario", "La compañía de seguros", "El propietario de la póliza"]', 0, 'A contingent (secondary) beneficiary receives the death benefit only if the primary beneficiary is deceased.', 'Un beneficiario contingente (secundario) recibe el beneficio por muerte solo si el beneficiario primario ha fallecido.', true, '2026-01-14 22:54:57.332208', '2026-01-14 22:54:57.332208') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e1a93370-fd06-44ed-b117-087648b386aa', 'life_insurance', NULL, 'What is the purpose of the Texas Guaranty Association for life insurance?', '¿Cuál es el propósito de la Asociación de Garantía de Texas para el seguro de vida?', '["To sell insurance", "To protect policyholders if their insurer becomes insolvent", "To regulate insurance rates", "To issue licenses"]', '["Vender seguros", "Proteger a los titulares de pólizas si su asegurador se vuelve insolvente", "Regular las tasas de seguros", "Emitir licencias"]', 1, 'The Texas Life and Health Insurance Guaranty Association protects policyholders by providing coverage if their insurance company becomes insolvent.', 'La Asociación de Garantía de Seguros de Vida y Salud de Texas protege a los titulares de pólizas proporcionando cobertura si su compañía de seguros se vuelve insolvente.', true, '2026-01-14 23:06:37.627998', '2026-01-14 23:06:37.627998') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e6b05ce2-a165-4209-8f79-0f61a4a660fe', 'life_insurance', NULL, 'What is the fixed period settlement option?', '¿Qué es la opción de liquidación de período fijo?', '["Death benefit paid in equal installments over a specified period", "Lump sum payment", "Interest only", "Life income"]', '["Beneficio por muerte pagado en cuotas iguales durante un período especificado", "Pago de suma global", "Solo interés", "Ingreso vitalicio"]', 0, 'Fixed period settlement pays the death benefit and interest in equal installments over a chosen time period.', 'La liquidación de período fijo paga el beneficio por muerte e interés en cuotas iguales durante un período de tiempo elegido.', true, '2026-01-14 22:54:57.401853', '2026-01-14 22:54:57.401853') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e6e00041-0cb6-4c2e-a554-5f2385d3e5aa', 'life_insurance', NULL, 'What is an annuity''s accumulation period?', '¿Qué es el período de acumulación de una anualidad?', '["When payments are received", "The time during which premiums are paid and funds grow", "After the annuitant dies", "The grace period"]', '["Cuando se reciben los pagos", "El tiempo durante el cual se pagan las primas y los fondos crecen", "Después de que el rentista muere", "El período de gracia"]', 1, 'The accumulation period is the phase during which premiums are paid into the annuity and the funds grow tax-deferred.', 'El período de acumulación es la fase durante la cual se pagan las primas en la anualidad y los fondos crecen con impuestos diferidos.', true, '2026-01-14 23:06:37.538493', '2026-01-14 23:06:37.538493') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e9a03872-eef2-4a28-aeec-29042d064949', 'life_insurance', NULL, 'When must insurable interest exist for life insurance?', '¿Cuándo debe existir el interés asegurable para el seguro de vida?', '["At the time of application", "At the time of death", "At policy renewal", "At any time"]', '["Al momento de la solicitud", "Al momento de la muerte", "En la renovación de la póliza", "En cualquier momento"]', 0, 'For life insurance, insurable interest must exist at the time of application, not at the time of death.', 'Para el seguro de vida, el interés asegurable debe existir al momento de la solicitud, no al momento de la muerte.', true, '2026-01-14 22:54:57.386338', '2026-01-14 22:54:57.386338') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('eaa44d2f-fde6-49e8-8879-bbb8dde7eaa2', 'life_insurance', NULL, 'What is a non-qualified annuity?', '¿Qué es una anualidad no calificada?', '["An annuity purchased with after-tax dollars outside a retirement plan", "Pre-tax funded", "Only for retirement plans", "Group annuity"]', '["Una anualidad comprada con dólares después de impuestos fuera de un plan de jubilación", "Financiada antes de impuestos", "Solo para planes de jubilación", "Anualidad grupal"]', 0, 'A non-qualified annuity is purchased with after-tax money and only the earnings are taxable upon withdrawal.', 'Una anualidad no calificada se compra con dinero después de impuestos y solo las ganancias son gravables al retiro.', true, '2026-01-14 23:01:15.779026', '2026-01-14 23:01:15.779026') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ec1ba495-a691-4edf-9c37-7c40ee4094d6', 'life_insurance', NULL, 'What is mortgage life insurance?', '¿Qué es el seguro de vida hipotecario?', '["Decreasing term insurance designed to pay off a mortgage balance", "Increasing coverage", "Permanent insurance", "Health insurance"]', '["Seguro a término decreciente diseñado para pagar un saldo hipotecario", "Cobertura creciente", "Seguro permanente", "Seguro de salud"]', 0, 'Mortgage life insurance is decreasing term insurance that pays off the remaining mortgage if the homeowner dies.', 'El seguro de vida hipotecario es seguro a término decreciente que paga la hipoteca restante si el propietario fallece.', true, '2026-01-14 23:01:15.685001', '2026-01-14 23:01:15.685001') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ec60ab67-7af6-4911-9443-84c86671f509', 'life_insurance', NULL, 'What additional license is required to sell variable life insurance?', '¿Qué licencia adicional se requiere para vender seguro de vida variable?', '["Securities license (FINRA)", "Real estate license", "Health insurance license only", "No additional license"]', '["Licencia de valores (FINRA)", "Licencia de bienes raíces", "Solo licencia de seguro de salud", "Sin licencia adicional"]', 0, 'Variable life insurance requires both an insurance license and a securities license because it involves investment products.', 'El seguro de vida variable requiere tanto una licencia de seguros como una licencia de valores porque involucra productos de inversión.', true, '2026-01-14 22:54:57.240421', '2026-01-14 22:54:57.240421') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ec7beeca-e043-4468-8ee5-acc02e9bc626', 'life_insurance', NULL, 'What is a primary beneficiary?', '¿Qué es un beneficiario primario?', '["The first person entitled to receive the death benefit", "The secondary recipient", "The insurance agent", "The policy owner"]', '["La primera persona con derecho a recibir el beneficio por muerte", "El destinatario secundario", "El agente de seguros", "El propietario de la póliza"]', 0, 'The primary beneficiary is first in line to receive the death benefit upon the insured''s death.', 'El beneficiario primario es el primero en la línea para recibir el beneficio por muerte al fallecer el asegurado.', true, '2026-01-14 22:54:57.32894', '2026-01-14 22:54:57.32894') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ecf0c72a-b965-4e30-a5b4-11192eb79955', 'life_insurance', NULL, 'What is the accelerated death benefit rider?', '¿Qué es el anexo de beneficio por muerte acelerado?', '["Allows early access to death benefit if the insured is terminally ill", "Increases death benefit", "Decreases premiums", "Adds cash value"]', '["Permite acceso anticipado al beneficio por muerte si el asegurado está terminalmente enfermo", "Aumenta el beneficio por muerte", "Disminuye las primas", "Agrega valor en efectivo"]', 0, 'The accelerated death benefit rider pays a portion of the death benefit early if the insured is diagnosed with a terminal illness.', 'El anexo de beneficio por muerte acelerado paga una porción del beneficio por muerte anticipadamente si el asegurado es diagnosticado con una enfermedad terminal.', true, '2026-01-14 22:54:57.346136', '2026-01-14 22:54:57.346136') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ee4a51fa-f908-4965-b6f8-85c08eb64b7f', 'life_insurance', NULL, 'What is an immediate annuity?', '¿Qué es una anualidad inmediata?', '["An annuity that begins payments within one year of purchase", "Payments start after many years", "Deferred annuity", "No payments ever"]', '["Una anualidad que comienza pagos dentro de un año de la compra", "Los pagos comienzan después de muchos años", "Anualidad diferida", "Sin pagos nunca"]', 0, 'An immediate annuity begins making payments shortly after a lump-sum premium is paid.', 'Una anualidad inmediata comienza a hacer pagos poco después de que se paga una prima de suma global.', true, '2026-01-14 22:54:57.433917', '2026-01-14 22:54:57.433917') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f058d8bf-7854-4fc3-ba68-3909d9b9ecf8', 'life_insurance', NULL, 'What is a fiduciary?', '¿Qué es un fiduciario?', '["Someone who holds a position of trust and must act in the best interest of another", "An insurance company", "A claims adjuster", "A marketing representative"]', '["Alguien que ocupa una posición de confianza y debe actuar en el mejor interés de otro", "Una compañía de seguros", "Un ajustador de reclamos", "Un representante de marketing"]', 0, 'A fiduciary is someone who is trusted to act in another person''s best interests, such as handling their money.', 'Un fiduciario es alguien en quien se confía para actuar en los mejores intereses de otra persona, como manejar su dinero.', true, '2026-01-14 22:54:57.201925', '2026-01-14 22:54:57.201925') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f4b71a3a-fa34-4eee-8255-6c31dfe1a7d6', 'life_insurance', NULL, 'What is the purpose of a spendthrift clause in a life insurance policy?', '¿Cuál es el propósito de una cláusula de derrochador en una póliza de seguro de vida?', '["To increase premiums", "To protect policy proceeds from the beneficiary''s creditors", "To reduce the death benefit", "To change the beneficiary"]', '["Aumentar las primas", "Proteger los beneficios de la póliza de los acreedores del beneficiario", "Reducir el beneficio por muerte", "Cambiar al beneficiario"]', 1, 'A spendthrift clause protects policy proceeds from being claimed by the beneficiary''s creditors before the proceeds are paid.', 'Una cláusula de derrochador protege los beneficios de la póliza de ser reclamados por los acreedores del beneficiario antes de que se paguen los beneficios.', true, '2026-01-14 23:06:37.574263', '2026-01-14 23:06:37.574263') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f518ebd7-aea3-4853-bca5-9aae1cc2289c', 'life_insurance', NULL, 'What types of exchanges qualify under Section 1035?', '¿Qué tipos de intercambios califican bajo la Sección 1035?', '["Life to life, annuity to annuity, life to annuity (but not annuity to life)", "Any insurance exchange", "Only annuities", "Only term insurance"]', '["Vida a vida, anualidad a anualidad, vida a anualidad (pero no anualidad a vida)", "Cualquier intercambio de seguros", "Solo anualidades", "Solo seguro a término"]', 0, 'Section 1035 allows life-to-life, annuity-to-annuity, and life-to-annuity exchanges, but not annuity-to-life.', 'La Sección 1035 permite intercambios vida-a-vida, anualidad-a-anualidad y vida-a-anualidad, pero no anualidad-a-vida.', true, '2026-01-14 23:01:15.742734', '2026-01-14 23:01:15.742734') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f52282ff-1986-4b04-bd0e-62294b956cae', 'life_insurance', NULL, 'What is the guaranteed insurability rider?', '¿Qué es el anexo de asegurabilidad garantizada?', '["Allows purchase of additional coverage at specific times without proof of insurability", "Requires medical exam for additions", "Decreases coverage", "Cancels the policy"]', '["Permite la compra de cobertura adicional en momentos específicos sin prueba de asegurabilidad", "Requiere examen médico para adiciones", "Disminuye la cobertura", "Cancela la póliza"]', 0, 'The guaranteed insurability rider allows buying additional coverage at specified dates without medical underwriting.', 'El anexo de asegurabilidad garantizada permite comprar cobertura adicional en fechas especificadas sin suscripción médica.', true, '2026-01-14 22:54:57.350298', '2026-01-14 22:54:57.350298') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f6244f0f-7fa9-4654-9d28-41040c9a76f6', 'life_insurance', NULL, 'What is the return of premium rider?', '¿Qué es el anexo de devolución de prima?', '["Returns premiums paid if the insured outlives the policy term", "No premium refund", "Reduces death benefit", "Increases coverage"]', '["Devuelve las primas pagadas si el asegurado sobrevive el término de la póliza", "Sin reembolso de prima", "Reduce el beneficio por muerte", "Aumenta la cobertura"]', 0, 'The return of premium rider refunds all premiums paid if the insured survives the term of the policy.', 'El anexo de devolución de prima reembolsa todas las primas pagadas si el asegurado sobrevive el término de la póliza.', true, '2026-01-14 23:01:15.622389', '2026-01-14 23:01:15.622389') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f750f8b4-b8c3-4280-9448-88d5598138e9', 'life_insurance', NULL, 'What is the common disaster clause?', '¿Qué es la cláusula de desastre común?', '["Determines who receives proceeds if insured and beneficiary die in same accident", "Increases death benefit", "Reduces premiums", "Changes policy term"]', '["Determina quién recibe los beneficios si el asegurado y el beneficiario mueren en el mismo accidente", "Aumenta el beneficio por muerte", "Reduce las primas", "Cambia el término de la póliza"]', 0, 'The common disaster clause specifies how benefits are paid if the insured and beneficiary die in the same event.', 'La cláusula de desastre común especifica cómo se pagan los beneficios si el asegurado y el beneficiario mueren en el mismo evento.', true, '2026-01-14 23:01:15.580942', '2026-01-14 23:01:15.580942') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fb7e4916-929b-4ab6-9a56-4f502e9f3a8d', 'life_insurance', NULL, 'What dividend option applies dividends toward premium payments?', '¿Qué opción de dividendos aplica los dividendos hacia pagos de primas?', '["Premium reduction", "Cash payment", "Paid-up additions", "Accumulate at interest"]', '["Reducción de prima", "Pago en efectivo", "Adiciones pagadas", "Acumular a interés"]', 0, 'The premium reduction option uses dividends to reduce the amount of premium due.', 'La opción de reducción de prima usa dividendos para reducir el monto de prima debido.', true, '2026-01-14 23:01:15.64291', '2026-01-14 23:01:15.64291') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fca750ae-e4e2-4ef2-819e-568f5f061b85', 'life_insurance', NULL, 'What is an HMO?', '¿Qué es un HMO?', '["Health Maintenance Organization - a managed care plan with a network of providers", "Home Mortgage Organization", "Health Medical Option", "Hospital Medical Organization"]', '["Organización de Mantenimiento de Salud - un plan de cuidado administrado con una red de proveedores", "Organización de Hipotecas Residenciales", "Opción Médica de Salud", "Organización Médica Hospitalaria"]', 0, 'An HMO is a type of health insurance plan that requires members to use in-network providers and get referrals for specialists.', 'Un HMO es un tipo de plan de seguro de salud que requiere que los miembros usen proveedores dentro de la red y obtengan referencias para especialistas.', true, '2026-01-14 18:28:35.673451', '2026-01-14 18:28:35.673451') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ff9d2f62-0a1d-4cec-aa79-8d66e71040c4', 'life_insurance', NULL, 'What is the 10% early withdrawal penalty for annuities?', '¿Qué es la penalidad del 10% por retiro anticipado para anualidades?', '["A federal tax penalty on taxable withdrawals before age 59½", "No penalty exists", "State penalty only", "Premium refund"]', '["Una penalidad fiscal federal sobre retiros gravables antes de los 59½ años", "No existe penalidad", "Solo penalidad estatal", "Reembolso de prima"]', 0, 'Withdrawals of taxable amounts from annuities before age 59½ are subject to a 10% IRS penalty plus income tax.', 'Los retiros de montos gravables de anualidades antes de los 59½ años están sujetos a una penalidad del 10% del IRS más impuesto sobre la renta.', true, '2026-01-14 23:01:15.781782', '2026-01-14 23:01:15.781782') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ffe03b52-4e91-4212-b1b8-d65c392b231c', 'life_insurance', NULL, 'What is the entire contract provision?', '¿Qué es la disposición de contrato completo?', '["The policy and application together constitute the entire agreement", "Only the policy matters", "Only the application matters", "Verbal agreements included"]', '["La póliza y la solicitud juntas constituyen el acuerdo completo", "Solo la póliza importa", "Solo la solicitud importa", "Acuerdos verbales incluidos"]', 0, 'The entire contract provision states that the policy and attached application make up the complete contract.', 'La disposición de contrato completo establece que la póliza y la solicitud adjunta componen el contrato completo.', true, '2026-01-14 23:01:15.523166', '2026-01-14 23:01:15.523166') ON CONFLICT (id) DO NOTHING;
